INSERT INTO informacionnotificacioncorreo (innocoid, innoconombre, innocoasunto, innococontenido, innocoenviarpiepagina, innocoenviarcopia, created_at, updated_at) VALUES
(1, 'piePagina', 'Pie Página Correo', '<p style=\"text-align: justify;\"><strong>Para su inter&eacute;s</strong>:&nbsp;<br /><br /><span style=\"font-size: 10pt;\">1. Este correo fue generado autom&aacute;ticamente, por favor no responda a &eacute;l.</span><br /><span style=\"font-size: 10pt;\">2. La informaci&oacute;n contenida en esta comunicaci&oacute;n es confidencial y s&oacute;lo puede ser utilizada por la persona natural o jur&iacute;dica a la cual est&aacute; dirigida.</span><br /><span style=\"font-size: 10pt;\">3. Si no es el destinatario autorizado, cualquier retenci&oacute;n, difusi&oacute;n, distribuci&oacute;n o copia de este mensaje, se encuentra prohibida y sancionada por la ley.</span><br /><span style=\"font-size: 10pt;\">4. Si por error recibe este mensaje, favor reenviar y borrar el mensaje recibido inmediatamente\". (Resoluci&oacute;n No. 089 de 2003 - Reglamento para el uso de Internet y Correo Electr&oacute;nico en el AGN. Art&iacute;culo 3&deg; numeral 5.</span></p>', 0, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(2, 'notificarRegistroUsuario', 'Creación de usuario y acceso al sistema de Elecciones', '<p style=\"text-align: justify;\">Estimado(a) <strong>nombreUsuario</strong>:</p>\r\n<p style=\"text-align: justify;\">La Cooperativa especializada de ahorro y cr&eacute;dito <strong>nombreEmpresa </strong>se permite informar que ha sido registrado(a) como usuario del Sistema de Elecciones, plataforma destinada a apoyar la gesti&oacute;n, control y seguimiento de los procesos de elecci&oacute;n y toma de decisiones de nuestros asociados y delegados.</p>\r\n<p style=\"text-align: justify;\">En su calidad de empleado(a) o asistente, se ha creado su cuenta de usuario, mediante la cual podr&aacute; acceder al sistema y gestionar las solicitudes y actividades que le sean asignadas.</p>\r\n<p style=\"text-align: justify;\">Datos de acceso al sistema:</p>\r\n<ul>\r\n<li style=\"text-align: justify;\">Usuario: <strong>nickUsuario</strong></li>\r\n<li style=\"text-align: justify;\">Contrase&ntilde;a inicial: <strong>contrasenaUsuario</strong></li>\r\n<li style=\"text-align: justify;\">Direcci&oacute;n de acceso: <strong><a href=\"\\&quot;urlSistema\\&quot;\">urlSistema</a></strong></li>\r\n</ul>\r\n<p style=\"text-align: justify;\">Por seguridad, tenga en cuenta que la contrase&ntilde;a proporcionada es de uso inicial. Al ingresar por primera vez al sistema, se le solicitar&aacute; realizar el cambio de contrase&ntilde;a antes de continuar.</p>\r\n<p style=\"text-align: justify;\">Si presenta alguna dificultad para ingresar al sistema, comun&iacute;quese con el &aacute;rea encargada del soporte de la plataforma.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Cordialmente,</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><em><strong>nombreEmpresa</strong></em><br><em><strong>Sistema de Elecciones</strong></em></p>', 1, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(3, 'notificarRegistroAspiranteDelegado', 'ELECCIONES DE DELEGADOS PARA EL PERIODO 2027 - 2030', '<p style=\"text-align: justify;\">Apreciado(a) asociado(a) <strong>nombreAsociado</strong>:</p>\r\n<p style=\"text-align: justify;\">La Cooperativa especializada de ahorro y cr&eacute;dito<strong> nombreEmpresa&nbsp;</strong>se permite informar que, en su calidad de asociado(a) h&aacute;bil y candidato(a) aspirante a tituloEleccion, le ha sido asignado el siguiente n&uacute;mero de inscripci&oacute;n:</p>\r\n<p style=\"text-align: justify;\">N&uacute;mero de inscripci&oacute;n: <strong>numeroAsignado</strong><br>Agencia: <strong>nombreAgencia</strong></p>\r\n<p style=\"text-align: justify;\">Tenga en cuenta la siguiente informaci&oacute;n relacionada con el proceso electoral:</p>\r\n<ol>\r\n<li style=\"text-align: justify;\">Las elecciones se llevar&aacute;n a cabo el d&iacute;a 5 de noviembre de 2026.</li>\r\n<li style=\"text-align: justify;\">La jornada electoral se realizar&aacute; de manera virtual, a trav&eacute;s del siguiente enlace: https://elecciones.coopintegrate.com, y de manera presencial en lugarVotacion.</li>\r\n<li style=\"text-align: justify;\">Para participar en el proceso electoral, deber&aacute; mantener su condici&oacute;n de asociado(a) h&aacute;bil en todos los conceptos requeridos por la Cooperativa.</li>\r\n</ol>\r\n<p style=\"text-align: justify;\">Agradecemos su participaci&oacute;n y compromiso con el proceso democr&aacute;tico de la Cooperativa.</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\">Cordialmente,</p>\r\n<p style=\"text-align: justify;\">&nbsp;</p>\r\n<p style=\"text-align: justify;\"><strong><em>nombreEmpresa</em></strong><br><strong><em>Sistema de Elecciones</em></strong></p>', 1, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
INSERT INTO acta (actaid, actatitulo, actacontenido, created_at, updated_at) VALUES
(1, 'ACTA APERTURA DE ELECCIONES PARA EL anio', 'Siendo las hora_inicio en lugarEvento se da inicio Al proceso de elecciones para elegir miembros del tituloEleccion de sigla_empresa en la tituloEleccion, los Jurados: nombreJurados y testigo nombreTestigos quienes verifican que el procedimiento de apertura de elecciones.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(2, 'ACTA RESULTADOS DE ESCRUTINIO tituloEleccion anio', 'Siendo las horaCierre en lugarEvento donde se llevó  a cabo la tituloEleccion y donde  se  eligen  los miembros para el tituloEleccion, los Jurados: nombreJurados y testigo nombreTestigos quienes  conocen  el proceso  de elección electrónica.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(3, 'RESULTADOS DE ELECCIONES MIEMBROS DEL tituloEleccion anio', 'Siendo las horaCierre en lugarEvento los abajo firmantes fueron nombrados como jurados y testigo para el proceso de elecciones y certifican que los miembros de tituloEleccion fueron elegidos por los delegados hábiles de la tituloEleccion por el sistema uninominal de forma electrónica.', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(4, 'ACTA  DE APERTURA DE ELECCIONES DE DELEGADOS A LA XXXVI ASAMBLEA GENERAL EN MARZO DE 2027', 'Siendo las 8:00 de la mañana del día ocho (8) de noviembre del año dos mil veintiseis (2026) en el auditorio de la cooperativa en el Municipio de González Cesar se da  inicio a las elecciones de delegados, proceso de inscripción realizado del  3  al 14  de octubre de 2022  en las oficinas de Coopigon obteniendo un numero  en la lista  de aspirantes a delegados, el proceso  se realizara de  manera  virtual  de forma  presencial y no presencial  con acceso a pantalla del equipo de computo  para  que  sufragan los  asociados  por el aspirante de  su preferencia. \r\n\r\nLos  Jurados  están conformado por 2 asociados hábiles y el jefe  de riesgos de la cooperativa los cuales no están aspirando como delegados, dando cumplimiento al reglamento de elecciones, para el debido proceso de elecciones reciben lo siguiente:\r\n\r\nListado de sufragantes, asociados hábiles a corte del cinco (8) de noviembre de 2026.\r\nReglamento de elecciones de delegados para el periodo 2027-2030.\r\nPapelería requerida para impresión de actas de apertura y cierre de elecciones.\r\nEquipo de computo.\r\n \r\nPara mayor constancia firman los Jurados', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(5, 'ACTA  DE APERTURA DE ELECCIONES DE DELEGADOS A LA XXXVI ASAMBLEA GENERAL EN MARZO DE 2027', 'Siendo las 8:00 de la mañana del día ocho (8) de noviembre del año dos mil veintiseis (2026) en las oficinas de agencia de la cooperativa en el Municipio de Villa Caro se da inicio a las  elecciones de delegados, proceso  de inscripción realizado del  3  al 14  de octubre de 2026 en las oficinas de Coopigon obteniendo un numero en la lista  de aspirantes a delegados, el proceso  se realizara de  manera  virtual  de forma  presencial y no presencial  con acceso a pantalla del equipo de computo  para  que  sufragan los  asociados  por el aspirante de  su preferencia. \r\n\r\nLos  Jurados están conformado por un asociado hábil y Supernumerario de la  agencia de Coopigon en el Municipio de Villa Caro, los  cuales  no están aspirando como delegados, dando cumplimiento al reglamento de elecciones, para el debido proceso  de elecciones reciben lo siguiente:\r\n\r\nListado de sufragantes, asociados hábiles a corte del ocho (8) de noviembre de 2026.\r\nReglamento de elecciones de delegados para el periodo 2027-2030.\r\nPapelería requerida para impresión de actas de apertura y cierre de elecciones.\r\nEquipo de computo.\r\n \r\nPara mayor constancia firman los Jurados', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(6, 'RESULTADOS ELECCION DE DELEGADOS PARA LA ASAMBLEA GENERAL DEL PERIODO 2027-2030', 'Siendo las 16:00 horas del día 06 de noviembre de 2022 en Auditorio de COOPIGON los abajo firmantes fueron nombrados como jurados y testigos para el proceso de elecciones y certifican que los miembros de la Asamblea General fueron elegidos por los asociados hábiles de la Cooperativa Por el sistema uninominal de forma electrónica, como se puede observar a continuación:', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
(7, 'RESULTADOS ELECCION DE DELEGADOS PARA LA ASAMBLEA GENERAL DEL PERIODO 2027-2030', 'Siendo las 16:00 horas del día 06 de noviembre de 2022 en la oficina Agencia COOPIGON VILLA CARO los abajo firmantes fueron nombrados como jurados y testigos para el proceso de elecciones y certifican que los miembros de la Asamblea General fueron elegidos por los asociados hábiles de la Cooperativa por el sistema uninominal de forma electrónica, como se puede observar a continuación:', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP);
